package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.nbt.CompoundTag;import net.minecraft.world.item.*;import net.minecraft.world.level.Level;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.network.chat.Component;import java.util.*;
public class Fl01Item extends Item{
 public Fl01Item(Properties p){super(p);}public static CompoundTag data(ItemStack s){var n=s.get(net.minecraft.core.component.DataComponents.CUSTOM_DATA);return n==null?new CompoundTag():n.copyTag();}public static void data(ItemStack s,CompoundTag n){s.set(net.minecraft.core.component.DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(n));}/** Missing color choice, including older saved stacks, uses the original fully dark texture. */ public static boolean pink(ItemStack s){return data(s).getBoolean("Pink");}public static int fuel(ItemStack s){var n=data(s);return n.contains("Fuel")?Math.max(0,Math.min(Fl01Config.FUEL.get(),n.getInt("Fuel"))):0;}
 @Override public InteractionResultHolder<ItemStack>use(Level l,Player p,InteractionHand h){var s=p.getItemInHand(h);if(p.isShiftKeyDown()){if(!l.isClientSide){var n=data(s);n.putBoolean("Pink",!n.getBoolean("Pink"));data(s,n);p.displayClientMessage(Component.literal(n.getBoolean("Pink")?"FL-01: pink nose":"FL-01: dark nose"),true);}return InteractionResultHolder.sidedSuccess(s,l.isClientSide);}p.displayClientMessage(Component.literal("Load FL-01 onto an FL-LP launch platform."),true);return InteractionResultHolder.fail(s);}
 @Override public void appendHoverText(ItemStack s,Item.TooltipContext l,List<Component>t,TooltipFlag f){t.add(Component.literal("Fixed-wing aircraft | FL-LP required"));t.add(Component.literal("Sneak + use: select dark / pink nose"));t.add(Component.literal("Refuel on FL-LP with a Gasoline Jerrycan before launch."));t.add(Component.literal("Fuel: "+fuel(s)+" ticks | "+(data(s).getBoolean("Pink")?"Pink":"Dark")));}
}
